import{_ as t,o,c as a,a5 as l}from"./chunks/framework.DrDMl0tG.js";const i="/assets/robotiq_cloth_fold.B8By206E.png",f=JSON.parse('{"title":"Server Example: Robotiq Cloth Fold","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/server/robotiq_cloth_fold.md","filePath":"sections/examples/server/robotiq_cloth_fold.md"}'),s={name:"sections/examples/server/robotiq_cloth_fold.md"};function r(h,e,n,c,d,p){return o(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="server-example-robotiq-cloth-fold" tabindex="-1">Server Example: Robotiq Cloth Fold <a class="header-anchor" href="#server-example-robotiq-cloth-fold" aria-label="Permalink to &quot;Server Example: Robotiq Cloth Fold&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>A fixed-base Kinova arm with a wrist-mounted Robotiq 2F-85 folds a square cloth in half on a table. The pads hold one corner of the hanging cloth. The arm moves across the cloth while lowering it, so the lower half lies down on the table, then swings the held corner over onto the corner that touched down first. It holds the fold, unfolds the cloth along the same path, lifts it back up, restores the starting state, and repeats the 15-second cycle. All motion comes from joint PD control and physical contacts.</p><p>The cloth is a deformable object in contact with the gripper pads, the table and itself (see <a href="./../../DeformableObject.html">Deformable Objects</a>). It is solved together with the arm, the pads and the table (<a href="./../../DeformableObject.html#solving-deformables-together-with-the-bodies"><code>World::setMonolithicDeformables()</code></a>), so the squeeze of the pads and the weight of the cloth act on the arm within the same step. The arm and gripper are the model of <a href="./robotiq_gripper_mimic.html">Server Example: Robotiq Gripper Mimic</a>.</p><img src="'+i+'" alt="Kinova arm with a Robotiq 2F-85 folding a red cloth on a table" style="width:80%;"><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>robotiq_cloth_fold</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>Run the build-tree executable and connect <code>rayrai_tcp_viewer</code> to port 8080:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/robotiq_cloth_fold</span></span></code></pre></div><p>On Windows, run <code>build-examples/bin/robotiq_cloth_fold.exe</code> instead. The example discovers its resource folder relative to the executable or working directory. Normal RaiSim license discovery applies; use <code>--activation-key /path/to/activation.raisim</code> for an explicit license. <code>--port N</code> changes the server port. The example repeats until interrupted; <code>--cycles N</code> stops it after N cycles. <code>--headless</code> runs two cycles without a server and prints whether each one succeeded.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Loads <code>rsc/robotiq_2f85/kinova_robotiq.urdf</code>. Only the six arm joints and <code>robotiq_85_left_knuckle_joint</code> have PD gains; the five gripper followers stay passive under their URDF <code>&lt;mimic&gt;</code> constraints.</li><li>The cloth is a 0.2 m square of 19 x 19 particles weighing 20 g, with nearly inextensible edges, a bending modulus of 5e-5 N m, and self-collision, so the folded half rests on the lower half. Its elastic constraints are projected in 10 sweeps of each 1 ms step. Its particles collide as 6 mm spheres, close enough that the 4 mm thick pads cannot slip between them.</li><li>The pads clamp the corner face-on. The knuckle target lies beyond the closing angle at which the pads meet the cloth, so the knuckle PD squeezes it.</li><li>Friction coefficients: 0.8 between the pads and the cloth, 0.6 between the table and the cloth, and 0.3 between two layers of cloth. The folded half slides into place over the lower half instead of dragging it along.</li><li>The waypoints are positions of the gripper&#39;s <code>grasp_frame</code>, solved with <code>ArticulatedSystem::solveIK()</code> on a second, kinematics-only copy of the arm. The fold is planned when it begins: the cloth folds about the line half a diagonal from the corner that touched down, wherever that corner landed. The pads&#39; lower edges circle that line at 8 cm, a little less than the cloth between them and the fold, because a taut upper half would pull the lower half across the table.</li><li>A quintic time scaling covers each phase, and a cubic spline through the joint waypoints keeps the arm moving through them without stopping.</li><li>Each cycle checks that both pads held the cloth throughout, that the lower corner rested on the table when the fold began, that the held corner then lay within 8 cm of the lower corner while the lower corner slid less than 2 cm, and that the cloth hung clear of the table at the end.</li><li>After each cycle the example restores a checkpoint of the settled initial world, including robot and cloth state and solver history.</li><li>Controller updates run inside the RaisimServer world mutex and follow simulation time, so viewer pause and queued single-step pause the sequence.</li><li>The combined arm and gripper model reuses the bundled BSD-licensed Kinova and Robotiq descriptions and meshes; see the license files in <code>rsc/robotiq_2f85</code> and <code>rsc/kinova</code>.</li></ul>',13)])])}const b=t(s,[["render",r]]);export{f as __pageData,b as default};
